INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'വാക്കുകളുടെ ഘടന പഠിക്കുന്ന ശാഖ ______ ആണ്.', '', '', '', '', 'രൂപശാസ്ത്രം', 'ശരിയായ ഉത്തരം: രൂപശാസ്ത്രം');
