INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'അർത്ഥം പഠിക്കുന്ന ശാഖ ______ ആണ്.', '', '', '', '', 'ശബ്ദാർത്ഥശാസ്ത്രം', 'ശരിയായ ഉത്തരം: ശബ്ദാർത്ഥശാസ്ത്രം');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'സന്ദർഭവും ഉദ്ദേശ്യവും പഠിക്കുന്നത് ______ ആണ്.', '', '', '', '', 'പ്രയോഗശാസ്ത്രം', 'ശരിയായ ഉത്തരം: പ്രയോഗശാസ്ത്രം');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'ഭാഷാ ഡാറ്റയുടെ വലിയ ശേഖരം ______ ആണ്.', '', '', '', '', 'കോർപ്പസ്', 'ശരിയായ ഉത്തരം: കോർപ്പസ്');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'ചോദ്യത്തിന് മറുപടി നൽകുന്ന സംവിധാനം ______ സംവിധാനമാണ്.', '', '', '', '', 'ചോദ്യോത്തര', 'ശരിയായ ഉത്തരം: ചോദ്യോത്തര');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'സംസാരത്തെ എഴുത്താക്കുന്നത് ______ ആണ്.', '', '', '', '', 'ശബ്ദ-വാചക പരിവർത്തനം', 'ശരിയായ ഉത്തരം: ശബ്ദ-വാചക പരിവർത്തനം');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'എഴുത്തിനെ ശബ്ദമാക്കുന്നത് ______ ആണ്.', '', '', '', '', 'വാചക-ശബ്ദ പരിവർത്തനം', 'ശരിയായ ഉത്തരം: വാചക-ശബ്ദ പരിവർത്തനം');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'സമാന രേഖകളെ കൂട്ടങ്ങളാക്കുന്നത് ______ ആണ്.', '', '', '', '', 'ക്ലസ്റ്ററിംഗ്', 'ശരിയായ ഉത്തരം: ക്ലസ്റ്ററിംഗ്');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'വാചക സാദൃശ്യം അളക്കാൻ ______ സാദൃശ്യം ഉപയോഗിക്കാം.', '', '', '', '', 'കോസൈൻ', 'ശരിയായ ഉത്തരം: കോസൈൻ');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'ഒരേ വാക്കിന് പല അർത്ഥങ്ങൾ വരുന്നത് ______ പ്രശ്നമാണ്.', '', '', '', '', 'പദദ്വയാർഥ്യം', 'ശരിയായ ഉത്തരം: പദദ്വയാർഥ്യം');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Fill in the Blanks', 'എളുപ്പം', 1, 'മോഡൽ പ്രകടനം പരിശോധിക്കുന്ന പ്രക്രിയ ______ ആണ്.', '', '', '', '', 'വിലയിരുത്തൽ', 'ശരിയായ ഉത്തരം: വിലയിരുത്തൽ');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'NLP എന്താണ്?', '', '', '', '', 'മനുഷ്യഭാഷയെ കമ്പ്യൂട്ടർ വിശകലനം ചെയ്യുകയും മനസ്സിലാക്കുകയും സൃഷ്ടിക്കുകയും ചെയ്യുന്ന മേഖലയാണ് NLP.', 'മനുഷ്യഭാഷയെ കമ്പ്യൂട്ടർ വിശകലനം ചെയ്യുകയും മനസ്സിലാക്കുകയും സൃഷ്ടിക്കുകയും ചെയ്യുന്ന മേഖലയാണ് NLP.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ടോക്കണൈസേഷൻ എന്താണ്?', '', '', '', '', 'വാചകത്തെ വാക്ക്, ഉപവാക്ക് അല്ലെങ്കിൽ അക്ഷരം പോലുള്ള ചെറിയ ടോക്കണുകളായി വിഭജിക്കുന്ന പ്രക്രിയയാണ്.', 'വാചകത്തെ വാക്ക്, ഉപവാക്ക് അല്ലെങ്കിൽ അക്ഷരം പോലുള്ള ചെറിയ ടോക്കണുകളായി വിഭജിക്കുന്ന പ്രക്രിയയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'സ്റ്റമ്മിംഗ് എന്താണ്?', '', '', '', '', 'വാക്കുകളുടെ അറ്റങ്ങൾ നീക്കം ചെയ്ത് മൂലരൂപസദൃശമായ രൂപം കണ്ടെത്തുന്ന രീതിയാണ്.', 'വാക്കുകളുടെ അറ്റങ്ങൾ നീക്കം ചെയ്ത് മൂലരൂപസദൃശമായ രൂപം കണ്ടെത്തുന്ന രീതിയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ലമ്മറ്റൈസേഷൻ എന്താണ്?', '', '', '', '', 'വാക്കിന്റെ അടിസ്ഥാന നിഘണ്ടുരൂപം കണ്ടെത്തുന്ന പ്രക്രിയയാണ്.', 'വാക്കിന്റെ അടിസ്ഥാന നിഘണ്ടുരൂപം കണ്ടെത്തുന്ന പ്രക്രിയയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ഭാഷാഭാഗ നിർണ്ണയം എന്താണ്?', '', '', '', '', 'വാക്ക് നാമം, ക്രിയ, വിശേഷണം തുടങ്ങിയ ഏത് വ്യാകരണ വിഭാഗത്തിൽപ്പെടുന്നു എന്ന് കണ്ടെത്തുന്നതാണ്.', 'വാക്ക് നാമം, ക്രിയ, വിശേഷണം തുടങ്ങിയ ഏത് വ്യാകരണ വിഭാഗത്തിൽപ്പെടുന്നു എന്ന് കണ്ടെത്തുന്നതാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'നാമപ്പെട്ട ഘടക തിരിച്ചറിയൽ എന്താണ്?', '', '', '', '', 'വ്യക്തി, സ്ഥലം, സംഘടന, തീയതി തുടങ്ങിയ പേരുള്ള ഘടകങ്ങളെ കണ്ടെത്തുന്നതാണ്.', 'വ്യക്തി, സ്ഥലം, സംഘടന, തീയതി തുടങ്ങിയ പേരുള്ള ഘടകങ്ങളെ കണ്ടെത്തുന്നതാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ഭാവവിശകലനം എന്താണ്?', '', '', '', '', 'വാചകത്തിന്റെ അനുകൂല, പ്രതികൂല, നിഷ്പക്ഷ വികാര സ്വഭാവം കണ്ടെത്തുന്നതാണ്.', 'വാചകത്തിന്റെ അനുകൂല, പ്രതികൂല, നിഷ്പക്ഷ വികാര സ്വഭാവം കണ്ടെത്തുന്നതാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'യന്ത്ര വിവർത്തനം എന്താണ്?', '', '', '', '', 'ഒരു ഭാഷയിലെ വാചകം മറ്റൊരു ഭാഷയിലേക്ക് കമ്പ്യൂട്ടർ ഉപയോഗിച്ച് മാറ്റുന്നതാണ്.', 'ഒരു ഭാഷയിലെ വാചകം മറ്റൊരു ഭാഷയിലേക്ക് കമ്പ്യൂട്ടർ ഉപയോഗിച്ച് മാറ്റുന്നതാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'വാചക സംഗ്രഹണം എന്താണ്?', '', '', '', '', 'ദീർഘമായ രേഖയിലെ പ്രധാന വിവരങ്ങൾ ചുരുക്കി നൽകുന്നതാണ്.', 'ദീർഘമായ രേഖയിലെ പ്രധാന വിവരങ്ങൾ ചുരുക്കി നൽകുന്നതാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'വേഡ് എംബെഡിംഗ് എന്താണ്?', '', '', '', '', 'വാക്കുകളെ അർത്ഥബന്ധം പ്രതിഫലിപ്പിക്കുന്ന സംഖ്യാ വെക്ടറുകളായി പ്രതിനിധീകരിക്കുന്ന രീതിയാണ്.', 'വാക്കുകളെ അർത്ഥബന്ധം പ്രതിഫലിപ്പിക്കുന്ന സംഖ്യാ വെക്ടറുകളായി പ്രതിനിധീകരിക്കുന്ന രീതിയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ടി.എഫ്.-ഐ.ഡി.എഫ്. എന്താണ്?', '', '', '', '', 'രേഖയിൽ വാക്കിന്റെ ആവൃത്തിയും രേഖാസമൂഹത്തിലെ അപൂർവതയും പരിഗണിച്ച് അതിന്റെ പ്രാധാന്യം അളക്കുന്ന രീതിയാണ്.', 'രേഖയിൽ വാക്കിന്റെ ആവൃത്തിയും രേഖാസമൂഹത്തിലെ അപൂർവതയും പരിഗണിച്ച് അതിന്റെ പ്രാധാന്യം അളക്കുന്ന രീതിയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'എൻ-ഗ്രാം എന്താണ്?', '', '', '', '', 'തുടർച്ചയായ n ടോക്കണുകളുടെ കൂട്ടമാണ് എൻ-ഗ്രാം.', 'തുടർച്ചയായ n ടോക്കണുകളുടെ കൂട്ടമാണ് എൻ-ഗ്രാം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ഭാഷാ മാതൃക എന്താണ്?', '', '', '', '', 'ടോക്കൺക്രമങ്ങളുടെ സാധ്യത പഠിച്ച് അടുത്ത ടോക്കൺ പ്രവചിക്കാൻ കഴിയുന്ന മാതൃകയാണ്.', 'ടോക്കൺക്രമങ്ങളുടെ സാധ്യത പഠിച്ച് അടുത്ത ടോക്കൺ പ്രവചിക്കാൻ കഴിയുന്ന മാതൃകയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ട്രാൻസ്ഫോർമർ എന്താണ്?', '', '', '', '', 'ശ്രദ്ധാ സംവിധാനങ്ങൾ ഉപയോഗിച്ച് ഭാഷാ ശ്രേണിയിലെ ബന്ധങ്ങൾ പഠിക്കുന്ന ന്യൂറൽ വാസ്തുവിദ്യയാണ്.', 'ശ്രദ്ധാ സംവിധാനങ്ങൾ ഉപയോഗിച്ച് ഭാഷാ ശ്രേണിയിലെ ബന്ധങ്ങൾ പഠിക്കുന്ന ന്യൂറൽ വാസ്തുവിദ്യയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ശ്രദ്ധാ സംവിധാനം എന്താണ്?', '', '', '', '', 'ഒരു ടോക്കണിന് മറ്റുള്ള ടോക്കണുകളിൽ ഏതിനാണ് കൂടുതൽ പ്രാധാന്യമെന്ന് കണക്കാക്കുന്ന സംവിധാനമാണ്.', 'ഒരു ടോക്കണിന് മറ്റുള്ള ടോക്കണുകളിൽ ഏതിനാണ് കൂടുതൽ പ്രാധാന്യമെന്ന് കണക്കാക്കുന്ന സംവിധാനമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'LSTM എന്താണ്?', '', '', '', '', 'ഗേറ്റുകളും മെമ്മറി ഘടനയും ഉപയോഗിച്ച് ദീർഘകാല ആശ്രിതത്വങ്ങൾ കൈകാര്യം ചെയ്യുന്ന ആവർത്തന മാതൃകയാണ്.', 'ഗേറ്റുകളും മെമ്മറി ഘടനയും ഉപയോഗിച്ച് ദീർഘകാല ആശ്രിതത്വങ്ങൾ കൈകാര്യം ചെയ്യുന്ന ആവർത്തന മാതൃകയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'വാചക വർഗീകരണം എന്താണ്?', '', '', '', '', 'വാചകങ്ങളെ മുൻനിശ്ചിത വിഭാഗങ്ങളിലേക്ക് മാറ്റുന്ന പ്രക്രിയയാണ്.', 'വാചകങ്ങളെ മുൻനിശ്ചിത വിഭാഗങ്ങളിലേക്ക് മാറ്റുന്ന പ്രക്രിയയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ചോദ്യോത്തര സംവിധാനം എന്താണ്?', '', '', '', '', 'സ്വാഭാവിക ഭാഷയിലെ ചോദ്യത്തിന് അനുയോജ്യമായ മറുപടി നൽകുന്ന സംവിധാനമാണ്.', 'സ്വാഭാവിക ഭാഷയിലെ ചോദ്യത്തിന് അനുയോജ്യമായ മറുപടി നൽകുന്ന സംവിധാനമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'കോർപ്പസ് എന്താണ്?', '', '', '', '', 'ഭാഷാ പഠനത്തിനും വിശകലനത്തിനുമായി ശേഖരിച്ച വലിയ വാചകസമാഹാരമാണ്.', 'ഭാഷാ പഠനത്തിനും വിശകലനത്തിനുമായി ശേഖരിച്ച വലിയ വാചകസമാഹാരമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'പദദ്വയാർഥ്യം എന്താണ്?', '', '', '', '', 'ഒരേ വാക്കിന് സന്ദർഭമനുസരിച്ച് വ്യത്യസ്ത അർത്ഥങ്ങൾ ഉണ്ടാകുന്ന പ്രശ്നമാണ്.', 'ഒരേ വാക്കിന് സന്ദർഭമനുസരിച്ച് വ്യത്യസ്ത അർത്ഥങ്ങൾ ഉണ്ടാകുന്ന പ്രശ്നമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'രൂപശാസ്ത്രം എന്താണ്?', '', '', '', '', 'വാക്കുകളുടെ ഘടനയും രൂപഭേദങ്ങളും പഠിക്കുന്ന ഭാഷാശാഖയാണ്.', 'വാക്കുകളുടെ ഘടനയും രൂപഭേദങ്ങളും പഠിക്കുന്ന ഭാഷാശാഖയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'വാക്യഘടനാശാസ്ത്രം എന്താണ്?', '', '', '', '', 'വാക്യത്തിലെ വാക്കുകളുടെ ക്രമവും വ്യാകരണബന്ധങ്ങളും പഠിക്കുന്ന ശാഖയാണ്.', 'വാക്യത്തിലെ വാക്കുകളുടെ ക്രമവും വ്യാകരണബന്ധങ്ങളും പഠിക്കുന്ന ശാഖയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ശബ്ദാർത്ഥശാസ്ത്രം എന്താണ്?', '', '', '', '', 'വാക്കുകളുടെയും വാക്യങ്ങളുടെയും അർത്ഥം പഠിക്കുന്ന ശാഖയാണ്.', 'വാക്കുകളുടെയും വാക്യങ്ങളുടെയും അർത്ഥം പഠിക്കുന്ന ശാഖയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'പ്രയോഗശാസ്ത്രം എന്താണ്?', '', '', '', '', 'സന്ദർഭവും സംസാരിക്കുന്നവന്റെ ഉദ്ദേശ്യവും പരിഗണിക്കുന്ന ഭാഷാശാഖയാണ്.', 'സന്ദർഭവും സംസാരിക്കുന്നവന്റെ ഉദ്ദേശ്യവും പരിഗണിക്കുന്ന ഭാഷാശാഖയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'ബഹുഭാഷാ NLP എന്താണ്?', '', '', '', '', 'ഒന്നിലധികം ഭാഷകളിൽ NLP പ്രവർത്തനങ്ങൾ നടത്താൻ കഴിയുന്ന സംവിധാനമാണ്.', 'ഒന്നിലധികം ഭാഷകളിൽ NLP പ്രവർത്തനങ്ങൾ നടത്താൻ കഴിയുന്ന സംവിധാനമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'മുൻസംസ്കരണം എന്താണ്?', '', '', '', '', 'അസംസ്കൃത വാചകത്തെ മോഡൽ പരിശീലനത്തിന് അനുയോജ്യമാക്കുന്ന ശുദ്ധീകരണവും വിഭജനവും ഉൾപ്പെടുന്ന ഘട്ടമാണ്.', 'അസംസ്കൃത വാചകത്തെ മോഡൽ പരിശീലനത്തിന് അനുയോജ്യമാക്കുന്ന ശുദ്ധീകരണവും വിഭജനവും ഉൾപ്പെടുന്ന ഘട്ടമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'NLPയിലെ പക്ഷപാതം എന്താണ്?', '', '', '', '', 'ഡാറ്റയിലോ മാതൃകയിലോ ഉള്ള അസമത്വം മൂലം ചില വിഭാഗങ്ങൾക്ക് അനീതിയായ ഫലങ്ങൾ ഉണ്ടാകുന്ന അവസ്ഥയാണ്.', 'ഡാറ്റയിലോ മാതൃകയിലോ ഉള്ള അസമത്വം മൂലം ചില വിഭാഗങ്ങൾക്ക് അനീതിയായ ഫലങ്ങൾ ഉണ്ടാകുന്ന അവസ്ഥയാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'NLPയിലെ സ്വകാര്യത എന്താണ്?', '', '', '', '', 'ഭാഷാ ഡാറ്റയിലെ വ്യക്തിഗത വിവരങ്ങൾ അനധികൃതമായി ഉപയോഗിക്കപ്പെടുന്നതിൽ നിന്ന് സംരക്ഷിക്കുന്ന ആശയമാണ്.', 'ഭാഷാ ഡാറ്റയിലെ വ്യക്തിഗത വിവരങ്ങൾ അനധികൃതമായി ഉപയോഗിക്കപ്പെടുന്നതിൽ നിന്ന് സംരക്ഷിക്കുന്ന ആശയമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'NLP മോഡൽ വിലയിരുത്തൽ എന്താണ്?', '', '', '', '', 'പരിശീലിച്ച മോഡൽ പുതിയ ഡാറ്റയിൽ എത്ര നന്നായി പ്രവർത്തിക്കുന്നു എന്ന് അളക്കുന്നതാണ്.', 'പരിശീലിച്ച മോഡൽ പുതിയ ഡാറ്റയിൽ എത്ര നന്നായി പ്രവർത്തിക്കുന്നു എന്ന് അളക്കുന്നതാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Short Answer', 'മധ്യമം', 2, 'വാചക സാദൃശ്യം എന്താണ്?', '', '', '', '', 'രണ്ട് വാചകങ്ങളുടെ അർത്ഥമോ ഉള്ളടക്കമോ എത്രത്തോളം സാമ്യമുള്ളതാണെന്ന് അളക്കുന്നതാണ്.', 'രണ്ട് വാചകങ്ങളുടെ അർത്ഥമോ ഉള്ളടക്കമോ എത്രത്തോളം സാമ്യമുള്ളതാണെന്ന് അളക്കുന്നതാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLP പൈപ്പ്‌ലൈനിലെ പ്രധാന ഘട്ടങ്ങൾ വിശദീകരിക്കുക.', '', '', '', '', 'ഡാറ്റ ശേഖരണം, ശുദ്ധീകരണം, ടോക്കണൈസേഷൻ, സംഖ്യാ പ്രതിനിധാനം, മോഡൽ പരിശീലനം, വിലയിരുത്തൽ, വിന്യാസം എന്നിവ പ്രധാന ഘട്ടങ്ങളാണ്.', 'ഡാറ്റ ശേഖരണം, ശുദ്ധീകരണം, ടോക്കണൈസേഷൻ, സംഖ്യാ പ്രതിനിധാനം, മോഡൽ പരിശീലനം, വിലയിരുത്തൽ, വിന്യാസം എന്നിവ പ്രധാന ഘട്ടങ്ങളാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ടോക്കണൈസേഷൻ, സ്റ്റമ്മിംഗ്, ലമ്മറ്റൈസേഷൻ എന്നിവ താരതമ്യം ചെയ്യുക.', '', '', '', '', 'ടോക്കണൈസേഷൻ വാചകത്തെ ചെറിയ ഘടകങ്ങളാക്കുന്നു. സ്റ്റമ്മിംഗ് വാക്കുകളുടെ അറ്റങ്ങൾ നീക്കം ചെയ്യുന്നു. ലമ്മറ്റൈസേഷൻ ഭാഷാ വിവരങ്ങൾ ഉപയോഗിച്ച് സാധുവായ അടിസ്ഥാന രൂപം കണ്ടെത്തുന്നു.', 'ടോക്കണൈസേഷൻ വാചകത്തെ ചെറിയ ഘടകങ്ങളാക്കുന്നു. സ്റ്റമ്മിംഗ് വാക്കുകളുടെ അറ്റങ്ങൾ നീക്കം ചെയ്യുന്നു. ലമ്മറ്റൈസേഷൻ ഭാഷാ വിവരങ്ങൾ ഉപയോഗിച്ച് സാധുവായ അടിസ്ഥാന രൂപം കണ്ടെത്തുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'വാചക വർഗീകരണം വിശദീകരിക്കുക.', '', '', '', '', 'വാചകത്തെ മുൻനിശ്ചിത വിഭാഗത്തിലേക്ക് മാറ്റുന്നതാണ് വർഗീകരണം. സ്പാം കണ്ടെത്തൽ, വാർത്താ വിഭാഗീകരണം, വികാര വർഗീകരണം എന്നിവ ഉദാഹരണങ്ങളാണ്.', 'വാചകത്തെ മുൻനിശ്ചിത വിഭാഗത്തിലേക്ക് മാറ്റുന്നതാണ് വർഗീകരണം. സ്പാം കണ്ടെത്തൽ, വാർത്താ വിഭാഗീകരണം, വികാര വർഗീകരണം എന്നിവ ഉദാഹരണങ്ങളാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ഭാവവിശകലനം വിശദീകരിക്കുക.', '', '', '', '', 'വാചകത്തിലെ അഭിപ്രായമോ വികാരധ്രുവീകരണമോ കണ്ടെത്തുന്നതാണ് ഭാവവിശകലനം. അനുകൂലം, പ്രതികൂലം, നിഷ്പക്ഷം തുടങ്ങിയ വിഭാഗങ്ങൾ ഉപയോഗിക്കാം.', 'വാചകത്തിലെ അഭിപ്രായമോ വികാരധ്രുവീകരണമോ കണ്ടെത്തുന്നതാണ് ഭാവവിശകലനം. അനുകൂലം, പ്രതികൂലം, നിഷ്പക്ഷം തുടങ്ങിയ വിഭാഗങ്ങൾ ഉപയോഗിക്കാം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'നാമപ്പെട്ട ഘടക തിരിച്ചറിയൽ വിശദീകരിക്കുക.', '', '', '', '', 'വ്യക്തി, സ്ഥലം, സംഘടന, തീയതി തുടങ്ങിയ ഘടകങ്ങളെ വാചകത്തിൽ നിന്ന് കണ്ടെത്തുന്നു. വിവരശേഖരണം, വാർത്താ വിശകലനം, ചോദ്യോത്തര സംവിധാനം എന്നിവയിൽ ഇത് പ്രയോജനപ്പെടുന്നു.', 'വ്യക്തി, സ്ഥലം, സംഘടന, തീയതി തുടങ്ങിയ ഘടകങ്ങളെ വാചകത്തിൽ നിന്ന് കണ്ടെത്തുന്നു. വിവരശേഖരണം, വാർത്താ വിശകലനം, ചോദ്യോത്തര സംവിധാനം എന്നിവയിൽ ഇത് പ്രയോജനപ്പെടുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'യന്ത്ര വിവർത്തനത്തിലെ വെല്ലുവിളികൾ വിശദീകരിക്കുക.', '', '', '', '', 'ഭാഷകളുടെ വ്യാകരണം, വാക്കുകളുടെ ക്രമം, പദദ്വയാർഥ്യം, സന്ദർഭം എന്നിവ വ്യത്യസ്തമാണ്. അതിനാൽ നേരിട്ടുള്ള വാക്ക്-വാക്ക് വിവർത്തനം എല്ലായ്പ്പോഴും ശരിയായ അർത്ഥം നൽകില്ല.', 'ഭാഷകളുടെ വ്യാകരണം, വാക്കുകളുടെ ക്രമം, പദദ്വയാർഥ്യം, സന്ദർഭം എന്നിവ വ്യത്യസ്തമാണ്. അതിനാൽ നേരിട്ടുള്ള വാക്ക്-വാക്ക് വിവർത്തനം എല്ലായ്പ്പോഴും ശരിയായ അർത്ഥം നൽകില്ല.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'വാചക സംഗ്രഹണത്തിന്റെ രീതികൾ വിശദീകരിക്കുക.', '', '', '', '', 'എക്സ്ട്രാക്ടീവ് രീതിയിൽ പ്രധാന വാക്യങ്ങൾ തിരഞ്ഞെടുക്കുന്നു. അബ്സ്ട്രാക്ടീവ് രീതിയിൽ ആശയം മനസ്സിലാക്കി പുതിയ ചുരുക്കം സൃഷ്ടിക്കുന്നു.', 'എക്സ്ട്രാക്ടീവ് രീതിയിൽ പ്രധാന വാക്യങ്ങൾ തിരഞ്ഞെടുക്കുന്നു. അബ്സ്ട്രാക്ടീവ് രീതിയിൽ ആശയം മനസ്സിലാക്കി പുതിയ ചുരുക്കം സൃഷ്ടിക്കുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'വേഡ് എംബെഡിംഗിന്റെ പ്രാധാന്യം വിശദീകരിക്കുക.', '', '', '', '', 'വാക്കുകളെ സംഖ്യാ വെക്ടറുകളാക്കി അർത്ഥസാദൃശ്യം പ്രതിനിധീകരിക്കാൻ ഇത് സഹായിക്കുന്നു. വർഗീകരണം, തിരച്ചിൽ, ശുപാർശ തുടങ്ങിയ പ്രവർത്തനങ്ങളിൽ ഉപയോഗിക്കാം.', 'വാക്കുകളെ സംഖ്യാ വെക്ടറുകളാക്കി അർത്ഥസാദൃശ്യം പ്രതിനിധീകരിക്കാൻ ഇത് സഹായിക്കുന്നു. വർഗീകരണം, തിരച്ചിൽ, ശുപാർശ തുടങ്ങിയ പ്രവർത്തനങ്ങളിൽ ഉപയോഗിക്കാം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ടി.എഫ്.-ഐ.ഡി.എഫ്. വിശദീകരിക്കുക.', '', '', '', '', 'രേഖയിലെ വാക്കിന്റെ ആവൃത്തിയും മുഴുവൻ രേഖാസമൂഹത്തിലെ അതിന്റെ അപൂർവതയും കണക്കിലെടുത്താണ് ഭാരം നൽകുന്നത്. രേഖയ്ക്ക് പ്രത്യേകമായ വാക്കുകൾക്ക് സാധാരണ കൂടുതൽ പ്രാധാന്യം ലഭിക്കും.', 'രേഖയിലെ വാക്കിന്റെ ആവൃത്തിയും മുഴുവൻ രേഖാസമൂഹത്തിലെ അതിന്റെ അപൂർവതയും കണക്കിലെടുത്താണ് ഭാരം നൽകുന്നത്. രേഖയ്ക്ക് പ്രത്യേകമായ വാക്കുകൾക്ക് സാധാരണ കൂടുതൽ പ്രാധാന്യം ലഭിക്കും.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'എൻ-ഗ്രാം ഭാഷാ മാതൃക വിശദീകരിക്കുക.', '', '', '', '', 'തുടർച്ചയായ n ടോക്കണുകളുടെ കൂട്ടത്തെ അടിസ്ഥാനമാക്കി അടുത്ത ടോക്കൺ സാധ്യത കണക്കാക്കുന്നു. ലളിതമാണെങ്കിലും ദീർഘസന്ദർഭം കൈകാര്യം ചെയ്യുന്നതിൽ പരിമിതിയുണ്ട്.', 'തുടർച്ചയായ n ടോക്കണുകളുടെ കൂട്ടത്തെ അടിസ്ഥാനമാക്കി അടുത്ത ടോക്കൺ സാധ്യത കണക്കാക്കുന്നു. ലളിതമാണെങ്കിലും ദീർഘസന്ദർഭം കൈകാര്യം ചെയ്യുന്നതിൽ പരിമിതിയുണ്ട്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'RNNയും LSTMയും വിശദീകരിക്കുക.', '', '', '', '', 'RNN ക്രമത്തിലുള്ള ഡാറ്റയിലെ മുൻ വിവരങ്ങൾ ഉപയോഗിക്കുന്നു. ദീർഘക്രമങ്ങളിൽ വിവരങ്ങൾ നഷ്ടപ്പെടുന്ന പ്രശ്നം കുറയ്ക്കാൻ LSTM ഗേറ്റുകളും മെമ്മറി ഘടനയും ഉപയോഗിക്കുന്നു.', 'RNN ക്രമത്തിലുള്ള ഡാറ്റയിലെ മുൻ വിവരങ്ങൾ ഉപയോഗിക്കുന്നു. ദീർഘക്രമങ്ങളിൽ വിവരങ്ങൾ നഷ്ടപ്പെടുന്ന പ്രശ്നം കുറയ്ക്കാൻ LSTM ഗേറ്റുകളും മെമ്മറി ഘടനയും ഉപയോഗിക്കുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ട്രാൻസ്ഫോർമർ വാസ്തുവിദ്യ വിശദീകരിക്കുക.', '', '', '', '', 'ശ്രദ്ധാ സംവിധാനത്തിലൂടെ ടോക്കണുകൾ തമ്മിലുള്ള ബന്ധം പഠിക്കുന്നതാണ് ട്രാൻസ്ഫോർമറിന്റെ പ്രധാന ആശയം. എൻകോഡർ, ഡീകോഡർ തുടങ്ങിയ ഘടനകൾ ഉപയോഗിക്കാം.', 'ശ്രദ്ധാ സംവിധാനത്തിലൂടെ ടോക്കണുകൾ തമ്മിലുള്ള ബന്ധം പഠിക്കുന്നതാണ് ട്രാൻസ്ഫോർമറിന്റെ പ്രധാന ആശയം. എൻകോഡർ, ഡീകോഡർ തുടങ്ങിയ ഘടനകൾ ഉപയോഗിക്കാം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ശ്രദ്ധാ സംവിധാനത്തിന്റെ പ്രവർത്തനം വിശദീകരിക്കുക.', '', '', '', '', 'ഒരു ടോക്കണിനെ പ്രതിനിധീകരിക്കുമ്പോൾ മറ്റ് ടോക്കണുകളിൽ ഏതിനാണ് കൂടുതൽ പ്രാധാന്യം നൽകേണ്ടത് എന്ന് ഭാരങ്ങൾ കണക്കാക്കുന്നു. ഇതിലൂടെ സന്ദർഭബന്ധങ്ങൾ കാര്യക്ഷമമായി പഠിക്കാം.', 'ഒരു ടോക്കണിനെ പ്രതിനിധീകരിക്കുമ്പോൾ മറ്റ് ടോക്കണുകളിൽ ഏതിനാണ് കൂടുതൽ പ്രാധാന്യം നൽകേണ്ടത് എന്ന് ഭാരങ്ങൾ കണക്കാക്കുന്നു. ഇതിലൂടെ സന്ദർഭബന്ധങ്ങൾ കാര്യക്ഷമമായി പഠിക്കാം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ചോദ്യോത്തര സംവിധാനത്തിന്റെ പ്രവർത്തനം വിശദീകരിക്കുക.', '', '', '', '', 'ചോദ്യം വിശകലനം ചെയ്ത് ആവശ്യമായ വിവരസ്രോതസ്സ് കണ്ടെത്തുന്നു. പ്രസക്തമായ ഉള്ളടക്കത്തിൽ നിന്ന് ഉത്തരം തിരഞ്ഞെടുക്കുകയോ സൃഷ്ടിക്കുകയോ ചെയ്യുന്നു.', 'ചോദ്യം വിശകലനം ചെയ്ത് ആവശ്യമായ വിവരസ്രോതസ്സ് കണ്ടെത്തുന്നു. പ്രസക്തമായ ഉള്ളടക്കത്തിൽ നിന്ന് ഉത്തരം തിരഞ്ഞെടുക്കുകയോ സൃഷ്ടിക്കുകയോ ചെയ്യുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLP മുൻസംസ്കരണത്തിന്റെ പ്രാധാന്യം വിശദീകരിക്കുക.', '', '', '', '', 'അസംസ്കൃത വാചകത്തിലെ പിശകുകൾ, ആവർത്തനങ്ങൾ, അക്ഷരരൂപ വ്യത്യാസങ്ങൾ എന്നിവ കൈകാര്യം ചെയ്യുന്നു. മോഡലിന് സ്ഥിരതയുള്ള ഇൻപുട്ട് നൽകാൻ മുൻസംസ്കരണം സഹായിക്കുന്നു.', 'അസംസ്കൃത വാചകത്തിലെ പിശകുകൾ, ആവർത്തനങ്ങൾ, അക്ഷരരൂപ വ്യത്യാസങ്ങൾ എന്നിവ കൈകാര്യം ചെയ്യുന്നു. മോഡലിന് സ്ഥിരതയുള്ള ഇൻപുട്ട് നൽകാൻ മുൻസംസ്കരണം സഹായിക്കുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ബഹുഭാഷാ NLPയിലെ വെല്ലുവിളികൾ വിശദീകരിക്കുക.', '', '', '', '', 'വ്യത്യസ്ത ഭാഷകൾക്ക് വ്യത്യസ്ത ലിപി, വ്യാകരണം, രൂപശാസ്ത്രം, വാക്കുകളുടെ ക്രമം എന്നിവയുണ്ട്. ചില ഭാഷകൾക്ക് പരിശീലന ഡാറ്റ കുറവായിരിക്കും.', 'വ്യത്യസ്ത ഭാഷകൾക്ക് വ്യത്യസ്ത ലിപി, വ്യാകരണം, രൂപശാസ്ത്രം, വാക്കുകളുടെ ക്രമം എന്നിവയുണ്ട്. ചില ഭാഷകൾക്ക് പരിശീലന ഡാറ്റ കുറവായിരിക്കും.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'മലയാളം NLPയിൽ പരിഗണിക്കേണ്ട കാര്യങ്ങൾ വിശദീകരിക്കുക.', '', '', '', '', 'മലയാള ലിപി, വാക്കുകളുടെ രൂപഭേദങ്ങൾ, സംയുക്ത രൂപങ്ങൾ, വിഭക്തികൾ, ഭാഷാ ഡാറ്റയുടെ ലഭ്യത എന്നിവ പരിഗണിക്കണം. ഭാഷാ പ്രത്യേകതകൾക്ക് അനുയോജ്യമായ ഡാറ്റയും മുൻസംസ്കരണവും ആവശ്യമാണ്.', 'മലയാള ലിപി, വാക്കുകളുടെ രൂപഭേദങ്ങൾ, സംയുക്ത രൂപങ്ങൾ, വിഭക്തികൾ, ഭാഷാ ഡാറ്റയുടെ ലഭ്യത എന്നിവ പരിഗണിക്കണം. ഭാഷാ പ്രത്യേകതകൾക്ക് അനുയോജ്യമായ ഡാറ്റയും മുൻസംസ്കരണവും ആവശ്യമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLPയിലെ ഡാറ്റ പക്ഷപാതം വിശദീകരിക്കുക.', '', '', '', '', 'അസമതുലിത ഡാറ്റ, പക്ഷപാതമുള്ള ലേബലുകൾ, പ്രതിനിധാനക്കുറവ് എന്നിവ മോഡൽ പക്ഷപാതത്തിന് കാരണമാകാം. വിഭാഗംപ്രകാരമുള്ള വിലയിരുത്തൽ വഴി ഇത് കണ്ടെത്താം.', 'അസമതുലിത ഡാറ്റ, പക്ഷപാതമുള്ള ലേബലുകൾ, പ്രതിനിധാനക്കുറവ് എന്നിവ മോഡൽ പക്ഷപാതത്തിന് കാരണമാകാം. വിഭാഗംപ്രകാരമുള്ള വിലയിരുത്തൽ വഴി ഇത് കണ്ടെത്താം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLPയിലെ സ്വകാര്യതാ വെല്ലുവിളികൾ വിശദീകരിക്കുക.', '', '', '', '', 'ഇമെയിൽ, സംഭാഷണം, രേഖകൾ എന്നിവയിൽ വ്യക്തിഗത വിവരങ്ങൾ ഉണ്ടാകാം. അനാമീകരണം, പ്രവേശന നിയന്ത്രണം, ഡാറ്റ കുറയ്ക്കൽ എന്നിവ ഉപയോഗിച്ച് അപകടം കുറയ്ക്കാം.', 'ഇമെയിൽ, സംഭാഷണം, രേഖകൾ എന്നിവയിൽ വ്യക്തിഗത വിവരങ്ങൾ ഉണ്ടാകാം. അനാമീകരണം, പ്രവേശന നിയന്ത്രണം, ഡാറ്റ കുറയ്ക്കൽ എന്നിവ ഉപയോഗിച്ച് അപകടം കുറയ്ക്കാം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLP മോഡൽ വിലയിരുത്തൽ വിശദീകരിക്കുക.', '', '', '', '', 'പ്രവർത്തനത്തെ ആശ്രയിച്ച് കൃത്യത, സൂക്ഷ്മത, പൂർണ്ണത, എഫ്1 അളവ് തുടങ്ങിയവ ഉപയോഗിക്കാം. സ്വതന്ത്ര പരിശോധനാ ഡാറ്റയിൽ പ്രകടനം പരിശോധിക്കണം.', 'പ്രവർത്തനത്തെ ആശ്രയിച്ച് കൃത്യത, സൂക്ഷ്മത, പൂർണ്ണത, എഫ്1 അളവ് തുടങ്ങിയവ ഉപയോഗിക്കാം. സ്വതന്ത്ര പരിശോധനാ ഡാറ്റയിൽ പ്രകടനം പരിശോധിക്കണം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'വാചക സാദൃശ്യം എങ്ങനെ കണക്കാക്കാം?', '', '', '', '', 'വാചകങ്ങളെ വെക്ടറുകളാക്കി കോസൈൻ സാദൃശ്യം പോലുള്ള അളവുകൾ ഉപയോഗിക്കാം. തിരച്ചിൽ, പകർപ്പ് കണ്ടെത്തൽ, ശുപാർശ എന്നിവയിൽ ഇത് ഉപയോഗിക്കാം.', 'വാചകങ്ങളെ വെക്ടറുകളാക്കി കോസൈൻ സാദൃശ്യം പോലുള്ള അളവുകൾ ഉപയോഗിക്കാം. തിരച്ചിൽ, പകർപ്പ് കണ്ടെത്തൽ, ശുപാർശ എന്നിവയിൽ ഇത് ഉപയോഗിക്കാം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ഭാഷാ മാതൃകയുടെ പരിശീലനം വിശദീകരിക്കുക.', '', '', '', '', 'വലിയ വാചകസമാഹാരത്തിൽ ടോക്കൺക്രമങ്ങൾ ഉപയോഗിച്ച് അടുത്ത ടോക്കൺ പ്രവചിക്കാൻ മോഡൽ പരിശീലിപ്പിക്കുന്നു. പരിശീലനത്തിൽ പാരാമീറ്ററുകൾ ക്രമീകരിക്കുന്നു.', 'വലിയ വാചകസമാഹാരത്തിൽ ടോക്കൺക്രമങ്ങൾ ഉപയോഗിച്ച് അടുത്ത ടോക്കൺ പ്രവചിക്കാൻ മോഡൽ പരിശീലിപ്പിക്കുന്നു. പരിശീലനത്തിൽ പാരാമീറ്ററുകൾ ക്രമീകരിക്കുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'സംഭാഷണ AIയുടെ ഘടകങ്ങൾ വിശദീകരിക്കുക.', '', '', '', '', 'ഇൻപുട്ട് മനസ്സിലാക്കൽ, സംഭാഷണാവസ്ഥ കൈകാര്യം ചെയ്യൽ, പ്രതികരണം സൃഷ്ടിക്കൽ, ആവശ്യമെങ്കിൽ ശബ്ദ പരിവർത്തനം എന്നിവ പ്രധാന ഘടകങ്ങളാണ്.', 'ഇൻപുട്ട് മനസ്സിലാക്കൽ, സംഭാഷണാവസ്ഥ കൈകാര്യം ചെയ്യൽ, പ്രതികരണം സൃഷ്ടിക്കൽ, ആവശ്യമെങ്കിൽ ശബ്ദ പരിവർത്തനം എന്നിവ പ്രധാന ഘടകങ്ങളാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'മനുഷ്യ പരിശോധനയുടെ പ്രാധാന്യം വിശദീകരിക്കുക.', '', '', '', '', 'നിയമപരമായ, വൈദ്യപരമായ, സെൻസിറ്റീവ് ഉള്ളടക്കങ്ങളിൽ NLP പിശകുകൾ ഗുരുതരമാകാം. അതിനാൽ ഉയർന്ന അപകടസാധ്യതയുള്ള ഉപയോഗങ്ങളിൽ മനുഷ്യ പരിശോധന ആവശ്യമാണ്.', 'നിയമപരമായ, വൈദ്യപരമായ, സെൻസിറ്റീവ് ഉള്ളടക്കങ്ങളിൽ NLP പിശകുകൾ ഗുരുതരമാകാം. അതിനാൽ ഉയർന്ന അപകടസാധ്യതയുള്ള ഉപയോഗങ്ങളിൽ മനുഷ്യ പരിശോധന ആവശ്യമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'രൂപശാസ്ത്ര വിശകലനം വിശദീകരിക്കുക.', '', '', '', '', 'വാക്കിന്റെ മൂലപദം, ഉപസർഗം, പ്രത്യയം, രൂപഭേദം തുടങ്ങിയ ഘടകങ്ങൾ കണ്ടെത്തുന്നതാണ് രൂപശാസ്ത്ര വിശകലനം. രൂപഭേദങ്ങൾ കൂടുതലുള്ള ഭാഷകളിൽ ഇത് പ്രധാനമാണ്.', 'വാക്കിന്റെ മൂലപദം, ഉപസർഗം, പ്രത്യയം, രൂപഭേദം തുടങ്ങിയ ഘടകങ്ങൾ കണ്ടെത്തുന്നതാണ് രൂപശാസ്ത്ര വിശകലനം. രൂപഭേദങ്ങൾ കൂടുതലുള്ള ഭാഷകളിൽ ഇത് പ്രധാനമാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'പാഴ്സിംഗ് വിശദീകരിക്കുക.', '', '', '', '', 'വാക്യത്തിലെ വാക്കുകൾ തമ്മിലുള്ള വ്യാകരണബന്ധം കണ്ടെത്തുന്നതാണ് പാഴ്സിംഗ്. വിവരശേഖരണം, ചോദ്യോത്തരം തുടങ്ങിയ പ്രവർത്തനങ്ങളിൽ ഇത് സഹായിക്കുന്നു.', 'വാക്യത്തിലെ വാക്കുകൾ തമ്മിലുള്ള വ്യാകരണബന്ധം കണ്ടെത്തുന്നതാണ് പാഴ്സിംഗ്. വിവരശേഖരണം, ചോദ്യോത്തരം തുടങ്ങിയ പ്രവർത്തനങ്ങളിൽ ഇത് സഹായിക്കുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLP വിന്യാസാനന്തര നിരീക്ഷണം വിശദീകരിക്കുക.', '', '', '', '', 'യഥാർത്ഥ ഉപയോക്തൃ ഡാറ്റ കാലക്രമേണ മാറാം. അതിനാൽ പ്രകടനം, പിശകുകൾ, പക്ഷപാതം, ഡാറ്റ മാറ്റം എന്നിവ നിരീക്ഷിച്ച് ആവശ്യമായപ്പോൾ മോഡൽ പുതുക്കണം.', 'യഥാർത്ഥ ഉപയോക്തൃ ഡാറ്റ കാലക്രമേണ മാറാം. അതിനാൽ പ്രകടനം, പിശകുകൾ, പക്ഷപാതം, ഡാറ്റ മാറ്റം എന്നിവ നിരീക്ഷിച്ച് ആവശ്യമായപ്പോൾ മോഡൽ പുതുക്കണം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLPയുടെ പ്രധാന പരിമിതികൾ വിശദീകരിക്കുക.', '', '', '', '', 'ഭാഷയുടെ അർത്ഥം സങ്കീർണ്ണവും സന്ദർഭാധിഷ്ഠിതവുമാണ്. ഡാറ്റ കുറവ്, പക്ഷപാതം, സ്വകാര്യത, കണക്കുകൂട്ടൽ ചെലവ് എന്നിവ പ്രധാന പരിമിതികളാണ്.', 'ഭാഷയുടെ അർത്ഥം സങ്കീർണ്ണവും സന്ദർഭാധിഷ്ഠിതവുമാണ്. ഡാറ്റ കുറവ്, പക്ഷപാതം, സ്വകാര്യത, കണക്കുകൂട്ടൽ ചെലവ് എന്നിവ പ്രധാന പരിമിതികളാണ്.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'ബഹുഭാഷാ ചോദ്യംബാങ്കിൽ ഭാഷാ ശുദ്ധി ഉറപ്പാക്കുന്നത് എങ്ങനെ?', '', '', '', '', 'ഭാഷാ ഫീൽഡ് വ്യക്തമായി സൂക്ഷിക്കുകയും ചോദ്യങ്ങൾ, ഓപ്ഷനുകൾ, ഉത്തരങ്ങൾ, വിശദീകരണങ്ങൾ തിരഞ്ഞെടുത്ത ഭാഷയിൽ പരിശോധിക്കുകയും വേണം. അനാവശ്യമായ മറ്റുഭാഷാ പദങ്ങൾ കണ്ടെത്താൻ ഭാഷാ പരിശോധന നടത്തണം.', 'ഭാഷാ ഫീൽഡ് വ്യക്തമായി സൂക്ഷിക്കുകയും ചോദ്യങ്ങൾ, ഓപ്ഷനുകൾ, ഉത്തരങ്ങൾ, വിശദീകരണങ്ങൾ തിരഞ്ഞെടുത്ത ഭാഷയിൽ പരിശോധിക്കുകയും വേണം. അനാവശ്യമായ മറ്റുഭാഷാ പദങ്ങൾ കണ്ടെത്താൻ ഭാഷാ പരിശോധന നടത്തണം.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Multiple Choice', 'മധ്യമം', 2, 'NLP സംവിധാനത്തിന്റെ ഗുണനിലവാരം മെച്ചപ്പെടുത്താൻ സഹായിക്കുന്ന നടപടികൾ തിരഞ്ഞെടുക്കുക.', 'ഗുണമേന്മയുള്ള ഡാറ്റ', 'ഭാഷാ ശുദ്ധീകരണം', 'സ്വതന്ത്ര പരിശോധനാ ഡാറ്റ', 'സ്ക്രീൻ തെളിച്ചം', 'ഗുണമേന്മയുള്ള ഡാറ്റ, ഭാഷാ ശുദ്ധീകരണം, സ്വതന്ത്ര പരിശോധനാ ഡാറ്റ', 'നല്ല ഡാറ്റയും ശരിയായ മുൻസംസ്കരണവും സ്വതന്ത്ര വിലയിരുത്തലും NLP മോഡലിന്റെ ഗുണനിലവാരം മെച്ചപ്പെടുത്തുന്നു.');
INSERT INTO mal_data_science_question_bank (subject, language, question_type, difficulty, marks, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('MAL-Natural Language Processing', 'മലയാളം', 'Long Answer', 'കഠിനം', 5, 'NLP സംവിധാനത്തിന്റെ ഗുണനിലവാരം ഉറപ്പാക്കുന്നതിനുള്ള പ്രധാന നടപടികൾ വിശദീകരിക്കുക.', 'ഗുണമേന്മയുള്ള ഭാഷാ ഡാറ്റ ശേഖരിക്കുക, ഡാറ്റ ശുദ്ധീകരിക്കുക, ശരിയായ മുൻസംസ്കരണം നടത്തുക, അനുയോജ്യമായ മാതൃക തിരഞ്ഞെടുക്കുക, സ്വതന്ത്ര പരിശോധനാ ഡാറ്റയിൽ വിലയിരുത്തുക, പക്ഷപാതവും സ്വകാര്യതയും പരിശോധിക്കുക, വിന്യാസത്തിനു ശേഷം പ്രകടനം നിരീക്ഷിക്കുക എന്നിവ പ്രധാന നടപടികളാണ്.', '', '', '', 'ഗുണമേന്മയുള്ള ഡാറ്റ, ശുദ്ധീകരണം, വിലയിരുത്തൽ, പക്ഷപാത പരിശോധന, സ്വകാര്യത, വിന്യാസാനന്തര നിരീക്ഷണം', 'NLP സംവിധാനത്തിന്റെ വിശ്വാസ്യതയ്ക്കായി ഡാറ്റ മുതൽ വിന്യാസാനന്തര നിരീക്ഷണം വരെയുള്ള മുഴുവൻ ജീവിതചക്രവും പരിശോധിക്കണം.');
